//! Firmware parity of the FX biquad cascade: the test-only ext40 reference against golden vectors
//! and the fast f32 path against the reference.
//!
//! The vectors are derived values only (output and state float32 words), generated by
//! `python tools/fx_biquad_check.py --golden` from the exact-arithmetic model that matches the
//! oracle's run of `0x120FDB` word for word (`docs/research/fx-dsp-map.md` section 6).

use super::biquad::{ext40_ref, Biquad, FW_BUTTERWORTH_FS4_WORDS};

const BLOCKS: usize = 16;
const FRAMES: usize = 4;
const STAGES: usize = 3;

