pub(super) const GOLDEN_STATES: [u32; 12] = [
    0xbd943355, 0x3ea0f9ef, 0x3da10fea, 0x3d1f5175, 0xbe5bf5e2, 0x3e13f66d, 0xbd8b9e85, 0x3db4f2c7,
    0xbd5ad0e1, 0xbda798c9, 0xbd2c7167, 0x3c82c0a8,
];

fn coef() -> [f32; 5] {
    FW_BUTTERWORTH_FS4_WORDS.map(f32::from_bits)
}

/// Golden input, channel `ch` (0 left, 1 right), sample `n`; exact in f32.
fn input(ch: usize, n: usize) -> f32 {
    let (mul, add, modulus) = if ch == 0 { (37, 11, 64) } else { (53, 5, 61) };
    ((mul * n + add) % modulus) as f32 / 64.0 - 0.5
}

/// Initial state word `k` of the golden scenario (`0.01 (k + 1) (-1)^k` rounded to f32).
fn initial_state(k: usize) -> f32 {
    let sign = if k.is_multiple_of(2) { 1.0 } else { -1.0 };
    (0.01 * (k + 1) as f64 * sign) as f32
}

/// Runs the reference cascade for one channel, block by block, returning outputs and final states.
fn run_reference(ch: usize) -> (Vec<f32>, [[f32; 2]; STAGES]) {
    let c = coef();
    // states are [s1L, s1R, s2L, s2R] per stage
    let mut st: [[f32; 2]; STAGES] =
        std::array::from_fn(|k| [initial_state(4 * k + ch), initial_state(4 * k + 2 + ch)]);
    let mut out: Vec<f32> = (0..BLOCKS * FRAMES).map(|n| input(ch, n)).collect();
    let (blocks, rest) = out.as_chunks_mut::<FRAMES>();
    assert!(rest.is_empty());
    for block in blocks {
        for s in &mut st {
            ext40_ref::stage(block, &c, s);
        }
    }
    (out, st)
}

fn words(v: &[f32]) -> Vec<u32> {
    v.iter().map(|x| x.to_bits()).collect()
}

#[test]
fn ext40_reference_matches_the_firmware_golden_vectors() {
    let (left, st_l) = run_reference(0);
    let (right, st_r) = run_reference(1);
    assert_eq!(words(&left), GOLDEN_LEFT, "left output words");
    assert_eq!(words(&right), GOLDEN_RIGHT, "right output words");
    for k in 0..STAGES {
        let got = [st_l[k][0], st_r[k][0], st_l[k][1], st_r[k][1]];
        assert_eq!(
            words(&got),
            GOLDEN_STATES[4 * k..4 * k + 4],
            "stage {k} state"
        );
    }
}

#[test]
fn butterworth_coefficients_are_a_unity_dc_low_pass_at_a_quarter_of_the_rate() {
    let [b0, b1, b2, a1, a2] = coef().map(f64::from);
    let s2 = std::f64::consts::SQRT_2;
    assert!((b0 - (2.0 - s2) / 2.0).abs() < 1e-6 && (b1 - 2.0 * b0).abs() < 1e-6);
    assert!((a2 - (2.0 - s2) / (2.0 + s2)).abs() < 1e-6 && a1 == 0.0);
    assert!(((b0 + b1 + b2) / (1.0 + a2) - 1.0).abs() < 1e-6);
}

/// Deterministic broadband test signal (integer LCG, no `rand`): about -6 dBFS peak.
fn noise(n: usize) -> Vec<f32> {
    let mut s = 0x1234_5678_u32;
    (0..n)
        .map(|i| {
            s = s.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            let u = (s >> 8) as f32 / (1u32 << 24) as f32 - 0.5;
            0.5 * u + 0.4 * (i as f32 * 0.05).sin()
        })
        .collect()
}

#[test]
fn fast_f32_path_tracks_the_reference_with_a_high_snr() {
    const N: usize = 8192;
    let c = coef();
    let x = noise(N);
    // Reference: three stages per block of four frames, like the routine.
    let mut want = x.clone();
    let mut st = [[0.0f32; 2]; STAGES];
    let (blocks, _) = want.as_chunks_mut::<FRAMES>();
    for block in blocks {
        for s in &mut st {
            ext40_ref::stage(block, &c, s);
        }
    }
    // Fast path: the engine's per-sample f32 transposed form II, three sections.
    let mut chain = [Biquad::identity(); STAGES];
    for b in &mut chain {
        b.c = c;
    }
    let got: Vec<f32> = x
        .iter()
        .map(|&v| chain.iter_mut().fold(v, |acc, b| b.process(0, acc)))
        .collect();
    let sig: f64 = want.iter().map(|&v| f64::from(v).powi(2)).sum();
    let err: f64 = want
        .iter()
        .zip(&got)
        .map(|(&w, &g)| (f64::from(w) - f64::from(g)).powi(2))
        .sum();
    let snr_db = 10.0 * (sig / err).log10();
    println!("fast f32 vs ext40 reference: SNR {snr_db:.1} dB over {N} samples");
    assert!(snr_db > 125.0, "SNR {snr_db:.1} dB");
}

#[test]
fn reference_stage_keeps_silence_silent_and_stores_truncated_words() {
    let mut x = [0.0f32; FRAMES];
    let mut s = [0.0f32; 2];
    ext40_ref::stage(&mut x, &coef(), &mut s);
    assert_eq!((x, s), ([0.0; FRAMES], [0.0; 2]));
    let mut x = [1.0f32, 0.0, 0.0, 0.0];
    ext40_ref::stage(&mut x, &coef(), &mut s);
    // y0 = b0 held in the register then stored as its upper 32 bits: exactly the b0 word
    assert_eq!(x[0].to_bits(), 0x3E95_F619);
}
